// Whisper LiveKit token mint
//
// Signs a short-lived LiveKit access token so a Whisper client can join
// a call's room. Room name = the shared call id (a UUID generated by
// the caller). Identity = the caller / callee's user id.
//
// Environment variables (set with `supabase secrets set ...`):
//   LIVEKIT_API_KEY     LiveKit Cloud project API key  (APIxxxxxxxx)
//   LIVEKIT_API_SECRET  LiveKit Cloud project secret
//
// Deploy:
//   supabase functions deploy whisper-livekit-token --no-verify-jwt
//
// We intentionally skip the Supabase JWT check (`--no-verify-jwt`) so a
// VoIP-pushed callee with a stale session can still mint a token. The
// room name is a UUID call id generated on the caller side — it isn't
// guessable from outside the conversation.

import { create, getNumericDate } from "https://deno.land/x/djwt@v3.0.2/mod.ts";

const API_KEY = Deno.env.get("LIVEKIT_API_KEY") ?? "";
const API_SECRET = Deno.env.get("LIVEKIT_API_SECRET") ?? "";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

async function sign(payload: Record<string, unknown>): Promise<string> {
  const encoder = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(API_SECRET),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign", "verify"],
  );
  return await create({ alg: "HS256", typ: "JWT" }, payload, key);
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }
  if (req.method !== "POST") {
    return new Response("method not allowed", { status: 405, headers: corsHeaders });
  }
  if (!API_KEY || !API_SECRET) {
    return new Response(
      JSON.stringify({ error: "LIVEKIT_API_KEY / LIVEKIT_API_SECRET not configured" }),
      { status: 500, headers: { ...corsHeaders, "content-type": "application/json" } },
    );
  }
  let body: { room?: string; identity?: string; name?: string };
  try {
    body = await req.json();
  } catch {
    return new Response(
      JSON.stringify({ error: "bad json" }),
      { status: 400, headers: { ...corsHeaders, "content-type": "application/json" } },
    );
  }
  const room = (body.room ?? "").trim();
  const identity = (body.identity ?? "").trim();
  if (!room || !identity) {
    return new Response(
      JSON.stringify({ error: "room and identity are required" }),
      { status: 400, headers: { ...corsHeaders, "content-type": "application/json" } },
    );
  }
  // 1 hour TTL is generous — calls rarely run that long, and the token
  // is only used once at room-join time anyway.
  const ttlSeconds = 60 * 60;
  const payload = {
    iss: API_KEY,
    sub: identity,
    name: body.name ?? identity,
    nbf: getNumericDate(0),
    exp: getNumericDate(ttlSeconds),
    video: {
      roomJoin: true,
      room,
      canPublish: true,
      canSubscribe: true,
      canPublishData: true,
    },
  };
  try {
    const token = await sign(payload);
    return new Response(
      JSON.stringify({ token, room, identity, ttl: ttlSeconds }),
      { headers: { ...corsHeaders, "content-type": "application/json" } },
    );
  } catch (e) {
    console.error("livekit token sign error", e);
    return new Response(
      JSON.stringify({ error: "sign failed" }),
      { status: 500, headers: { ...corsHeaders, "content-type": "application/json" } },
    );
  }
});
